/* Signature Serbian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Stefanmil": "From Stefan + mil (dear).", "Jelenaslava": "From Jelena + slava (glory).", "Nikolamir": "From Nikola + mir (peace).", "Milicaslava": "From Milica + slava.", "Aleksandarmil": "From Aleksandar + mil.", "Anamir": "From Ana + mir.", "Stefanmilić": "Signature surname in -ić style.", "Jelenaslavić": "Signature surname in -ić style.", "Nikolamirić": "Signature surname in -ić style.", "Anamirić": "Signature surname in -ić style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Stefanmil';
console.log(lookup(q));

